out = pathlib.Path(__file__).resolve().parents[1] / "src" / "i18n" / "locales"
out.mkdir(parents=True, exist_ok=True)
for i, lang in enumerate(L):
    data = {}
    for k, vals in S.items():
        assert len(vals) == 8, k
        node = data
        parts = k.split(".")
        for p in parts[:-1]:
            node = node.setdefault(p, {})
        node[parts[-1]] = vals[i]
    (out / f"{lang}.json").write_text(json.dumps(data, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
print(f"{len(S)} keys × {len(L)} languages")
